3	function isNeighbor([x1, y1]: Cell, [x2, y2]: Cell): boolean {
4	  const sameCell = x1 === x2 && y1 === y2;
5	  return !sameCell && Math.abs(x1 - x2) <= 1 && Math.abs(y1 - y2) <= 1;
6	}
7	
8	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
9	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
10	}
11	
12	export function nextGeneration(liveCells: Cell[]): Cell[] {
13	  return liveCells.filter((cell) => {
14	    const neighbors = countLiveNeighbors(cell, liveCells);
15	    return neighbors === 2 || neighbors === 3;
16	  });
17	}
